import{_ as a,C as i,o as r,c as s,ag as t,E as n}from"./chunks/framework.DMVuHR7L.js";const m=JSON.parse('{"title":"Connecting a device","description":"","frontmatter":{},"headers":[],"relativePath":"features/connecting.md","filePath":"features/connecting.md","lastUpdated":1778528554000}'),d={name:"features/connecting.md"};function c(l,e,h,p,u,b){const o=i("ThemeImage");return r(),s("div",null,[e[0]||(e[0]=t('<h1 id="connecting-a-device" tabindex="-1">Connecting a device <a class="header-anchor" href="#connecting-a-device" aria-label="Permalink to &quot;Connecting a device&quot;">​</a></h1><p>WebLogcat talks to the phone directly from the browser via <strong>WebUSB</strong>. There is no <code>adb</code> install on the laptop, no Android Studio, no proxy server — permission is granted through Chromium&#39;s standard device chooser and the on-device authorisation prompt.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A <strong>Chromium-based browser</strong>: Chrome, Edge, Brave, Opera, Arc. Firefox and Safari don&#39;t ship WebUSB, so the <strong>Connect a device</strong> button is disabled there.</li><li>The site served over <strong>HTTPS</strong> or from <code>localhost</code>. The hosted versions at <code>https://gabrielhuff.github.io/web-logcat/</code> (production) and <code>https://gabrielhuff.github.io/web-logcat/staging/</code> (staging) qualify; so does <code>npm run dev</code>.</li><li>An <strong>Android device</strong> with USB debugging enabled in <em>Settings → System → Developer options</em>.</li></ul><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2>',5)),n(o,{"src-dark":"/img/features/empty-state.png","src-light":"/img/features/empty-state-light.png",alt:"Connecting flow"}),e[1]||(e[1]=t('<ol><li>Plug the device in with a data-capable USB cable.</li><li>Click <strong>Connect a device</strong>. The browser shows its device chooser; pick your phone.</li><li>The phone shows the standard <em>Allow USB debugging?</em> prompt the first time. Tick <strong>Always allow from this computer</strong> if you want subsequent connects to be silent.</li><li>The dashboard mounts with a single Logcat tile filling the viewport. The topbar shows the device model and serial; the connection dot is green for real devices and amber for the simulator. Use <strong>+ Add widget</strong> to add more tiles.</li></ol><p>The browser remembers the WebUSB grant the same way it remembers any other permission — the second connect from the same browser+device pair is silent.</p><h2 id="switching-devices" tabindex="-1">Switching devices <a class="header-anchor" href="#switching-devices" aria-label="Permalink to &quot;Switching devices&quot;">​</a></h2><p>The device pill in the topbar opens a picker showing every device the browser has paired in this session, plus the simulator if it&#39;s been used. Pick a row to switch; the previous stream stays warm in the background so you can flip back without re-authorising.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause / fix</th></tr></thead><tbody><tr><td>Chooser is empty</td><td>Verify USB debugging is on, the device is unlocked, and the cable is data-capable. Replug and reload.</td></tr><tr><td>Pairing prompt never appears on the phone</td><td>Some OEMs hide it behind a notification. Pull down the shade.</td></tr><tr><td><code>Connect a device</code> is disabled</td><td>You&#39;re on Firefox / Safari, or the page isn&#39;t served from HTTPS / localhost.</td></tr><tr><td>Connection drops on screen-off</td><td>Some manufacturers cut USB after sleep. Disable screen-locked-off behaviour or keep the screen awake.</td></tr><tr><td>Mirror shows &quot;device not supported&quot;</td><td>Mirror needs <code>scrcpy</code> v2.7 capabilities. Older / very locked-down devices may refuse the push.</td></tr></tbody></table><p>If the chooser shows the phone but the connect step fails, check the browser console — the toast message comes from <code>friendlyConnectError()</code> in <a href="https://github.com/gabrielhuff/web-logcat/blob/main/src/lib/adb.ts" target="_blank" rel="noreferrer"><code>lib/adb.ts</code></a> and the underlying error usually points at the cause (timeout, permission denied, USB endpoint busy).</p><h2 id="don-t-have-a-phone" tabindex="-1">Don&#39;t have a phone? <a class="header-anchor" href="#don-t-have-a-phone" aria-label="Permalink to &quot;Don&#39;t have a phone?&quot;">​</a></h2><p>Click <strong>fake data</strong> on the empty state. The dashboard runs against the <a href="./simulator">simulated stream</a> so every widget renders against in-memory fixtures.</p><h2 id="device-proxy" tabindex="-1">Device Proxy <a class="header-anchor" href="#device-proxy" aria-label="Permalink to &quot;Device Proxy&quot;">​</a></h2><p>WebUSB takes an exclusive claim on the device&#39;s USB interface, so while WebLogcat is connected nothing else (Android Studio, scrcpy, <code>adb shell</code>) can talk to the same phone. It also can&#39;t reach <strong>emulators</strong> or <strong>Wi-Fi-attached</strong> devices, and Firefox / Safari don&#39;t ship WebUSB at all.</p><p><a href="https://tools.google.com/dlpage/android_web_device_proxy" target="_blank" rel="noreferrer">Android Web Device Proxy (WDP)</a> is a small daemon you install alongside the SDK. It multiplexes through your local <code>adb</code> server so multiple tools can share the device, and it exposes everything <code>adb devices</code> sees — emulators included — to web pages on <code>localhost</code>. WebLogcat speaks WDP&#39;s WebSocket protocol natively (the same one <a href="https://ui.perfetto.dev" target="_blank" rel="noreferrer">Perfetto&#39;s UI</a> uses).</p><div class="info custom-block"><p class="custom-block-title">Opt-in flag</p><p>The WDP transport is currently behind a feature flag while the wire protocol gets verified against real devices. Visit the app once with <code>?wdp=1</code> appended to the URL to enable it (the flag sticks via <code>localStorage</code>; the query param is stripped on read). <code>?wdp=0</code> clears it.</p></div><h3 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h3><ol><li>Install the WDP daemon from the link above and let it start.</li><li>Plug in the device, start the emulator, or <code>adb connect &lt;ip:port&gt;</code> — whatever brings the device into <code>adb devices</code>.</li><li>Open WebLogcat. The empty state shows a <strong>Web Device Proxy is running</strong> panel with one row per device.</li><li>Click <strong>Connect</strong> on a device. The first time WebLogcat talks to WDP from this browser origin, WDP opens a Google-served approval popup; accept it and the connection completes.</li></ol><p>After approval, subsequent visits from this origin are silent. Per-device authorization (the <code>unauthorized</code> state on the phone) prompts a separate popup the first time you connect to that device.</p><h3 id="why-use-it-over-webusb" tabindex="-1">Why use it over WebUSB? <a class="header-anchor" href="#why-use-it-over-webusb" aria-label="Permalink to &quot;Why use it over WebUSB?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Need</th><th>WebUSB</th><th>Device Proxy</th></tr></thead><tbody><tr><td>Zero install</td><td>✅</td><td>Requires the daemon</td></tr><tr><td>Multiple devices visible at once</td><td>❌ (one chooser pick)</td><td>✅</td></tr><tr><td>Coexist with Android Studio / scrcpy / <code>adb</code></td><td>❌ (exclusive claim)</td><td>✅</td></tr><tr><td>Emulators</td><td>❌</td><td>✅</td></tr><tr><td>Wi-Fi-attached devices</td><td>❌</td><td>✅</td></tr><tr><td>Firefox / Safari</td><td>❌</td><td>✅ (any browser)</td></tr></tbody></table><h3 id="mechanics" tabindex="-1">Mechanics <a class="header-anchor" href="#mechanics" aria-label="Permalink to &quot;Mechanics&quot;">​</a></h3><p>The transport hooks into the same <code>Adb</code> session every widget uses, so all five tiles — Logcat, Shell, Dumpsys, Files, Mirror — work identically over the proxy. The implementation lives at <a href="https://github.com/gabrielhuff/web-logcat/tree/main/src/lib/wdp" target="_blank" rel="noreferrer"><code>src/lib/wdp/</code></a>:</p><ul><li><code>trackDevices.ts</code> subscribes to <code>ws://127.0.0.1:9167/track-devices-json</code> for the live device list.</li><li><code>transport.ts</code> implements yume-chan&#39;s <code>AdbTransport</code> interface — each service stream (<code>shell:</code>, <code>sync:</code>, …) opens its own <code>ws://127.0.0.1:9167/adb-json</code> WebSocket with a JSON header <code>{ header: { serialNumber, command } }</code>.</li></ul><p>If the daemon isn&#39;t running, the empty state shows a dismissible tip linking to the install page; clear <code>weblogcat:wdp-not-installed:dismissed:v1</code> in localStorage to bring it back.</p>',22))])}const v=a(d,[["render",c]]);export{m as __pageData,v as default};
